import { sql } from "drizzle-orm";
import {
  boolean,
  date,
  index,
  integer,
  jsonb,
  pgTable,
  text,
  timestamp,
  uniqueIndex,
  uuid,
} from "drizzle-orm/pg-core";

const timestamps = {
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date()),
};

// ---------------------------------------------------------------------------
// Better Auth tables (shape required by better-auth; ids are generated by it)
// ---------------------------------------------------------------------------

export const user = pgTable("user", {
  id: text("id").primaryKey(),
  name: text("name").notNull(),
  email: text("email").notNull().unique(),
  emailVerified: boolean("email_verified").notNull().default(false),
  image: text("image"),
  timezone: text("timezone").notNull().default("UTC"),
  phoneE164: text("phone_e164"),
  phoneVerifiedAt: timestamp("phone_verified_at", { withTimezone: true }),
  ...timestamps,
});

export const session = pgTable(
  "session",
  {
    id: text("id").primaryKey(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    token: text("token").notNull().unique(),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
    ipAddress: text("ip_address"),
    userAgent: text("user_agent"),
    ...timestamps,
  },
  (table) => [index("session_user_id_idx").on(table.userId)],
);

export const account = pgTable(
  "account",
  {
    id: text("id").primaryKey(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    accountId: text("account_id").notNull(),
    providerId: text("provider_id").notNull(),
    accessToken: text("access_token"),
    refreshToken: text("refresh_token"),
    idToken: text("id_token"),
    accessTokenExpiresAt: timestamp("access_token_expires_at", { withTimezone: true }),
    refreshTokenExpiresAt: timestamp("refresh_token_expires_at", { withTimezone: true }),
    scope: text("scope"),
    password: text("password"),
    ...timestamps,
  },
  (table) => [index("account_user_id_idx").on(table.userId)],
);

export const verification = pgTable(
  "verification",
  {
    id: text("id").primaryKey(),
    identifier: text("identifier").notNull(),
    value: text("value").notNull(),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
    ...timestamps,
  },
  (table) => [index("verification_identifier_idx").on(table.identifier)],
);

// ---------------------------------------------------------------------------
// Planner
// ---------------------------------------------------------------------------

export const weeks = pgTable(
  "weeks",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    isoYear: integer("iso_year").notNull(),
    isoWeek: integer("iso_week").notNull(),
    weekStartDate: date("week_start_date").notNull(),
    bigPictureDirection: text("big_picture_direction").notNull().default(""),
    /** Guards `big_picture_direction`. */
    version: integer("version").notNull().default(1),
    /** The week's free-form notes page. */
    notes: text("notes").notNull().default(""),
    /** Guards `notes` separately, so a long notes edit never conflicts with a direction edit. */
    notesVersion: integer("notes_version").notNull().default(1),
    ...timestamps,
  },
  (table) => [uniqueIndex("weeks_user_week_key").on(table.userId, table.isoYear, table.isoWeek)],
);

export const TASK_STATUSES = ["open", "done", "skipped"] as const;
export type TaskStatus = (typeof TASK_STATUSES)[number];
export const TASK_KINDS = ["weekly", "ad_hoc"] as const;
export type TaskKind = (typeof TASK_KINDS)[number];

export const tasks = pgTable(
  "tasks",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    weekId: uuid("week_id")
      .notNull()
      .references(() => weeks.id, { onDelete: "cascade" }),
    callId: uuid("call_id").references(() => calls.id, { onDelete: "set null" }),
    carriedOverFromTaskId: uuid("carried_over_from_task_id"),
    title: text("title").notNull(),
    kind: text("kind", { enum: TASK_KINDS }).notNull().default("weekly"),
    assignedDate: date("assigned_date"),
    status: text("status", { enum: TASK_STATUSES }).notNull().default("open"),
    skippedReason: text("skipped_reason"),
    position: integer("position").notNull().default(0),
    version: integer("version").notNull().default(1),
    completedAt: timestamp("completed_at", { withTimezone: true }),
    ...timestamps,
  },
  (table) => [
    index("tasks_week_id_idx").on(table.weekId),
    index("tasks_call_id_idx").on(table.callId),
  ],
);

// ---------------------------------------------------------------------------
// Planning schedule, phone verification, calls
// ---------------------------------------------------------------------------

export const SCHEDULE_CHANNELS = ["call", "email"] as const;
export type ScheduleChannel = (typeof SCHEDULE_CHANNELS)[number];

export const planningSchedules = pgTable(
  "planning_schedules",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: text("user_id")
      .notNull()
      .unique()
      .references(() => user.id, { onDelete: "cascade" }),
    enabled: boolean("enabled").notNull().default(false),
    channel: text("channel", { enum: SCHEDULE_CHANNELS }).notNull().default("email"),
    /** ISO weekday, 1 = Monday ... 7 = Sunday. */
    dayOfWeek: integer("day_of_week").notNull().default(7),
    /** Local wall-clock time, "HH:MM". */
    localTime: text("local_time").notNull().default("18:00"),
    timezone: text("timezone").notNull().default("UTC"),
    nextRunAt: timestamp("next_run_at", { withTimezone: true }),
    lastRunAt: timestamp("last_run_at", { withTimezone: true }),
    emailFallback: boolean("email_fallback").notNull().default(true),
    callConsentAt: timestamp("call_consent_at", { withTimezone: true }),
    callConsentVersion: text("call_consent_version"),
    ...timestamps,
  },
  (table) => [
    index("planning_schedules_due_idx")
      .on(table.nextRunAt)
      .where(sql`${table.enabled} = true`),
  ],
);

export const phoneVerifications = pgTable(
  "phone_verifications",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    phoneE164: text("phone_e164").notNull(),
    status: text("status", { enum: ["pending", "approved", "expired"] })
      .notNull()
      .default("pending"),
    attempts: integer("attempts").notNull().default(0),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
    ...timestamps,
  },
  (table) => [index("phone_verifications_user_idx").on(table.userId, table.createdAt)],
);

export const CALL_STATUSES = [
  "queued",
  "ringing",
  "in_progress",
  "ended",
  "no_answer",
  "failed",
  "processed",
] as const;
export type CallStatus = (typeof CALL_STATUSES)[number];

/** What a processed call changed, so the import can be undone precisely. */
export type CallImportResult = {
  taskIds: string[];
  direction: { set: boolean; value: string } | null;
  /** Exact text appended to the week's notes, or null. */
  notesAppended: string | null;
  undoneAt?: string;
};

export const calls = pgTable(
  "calls",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    targetIsoYear: integer("target_iso_year").notNull(),
    targetIsoWeek: integer("target_iso_week").notNull(),
    provider: text("provider").notNull(),
    providerCallId: text("provider_call_id").unique(),
    status: text("status", { enum: CALL_STATUSES }).notNull().default("queued"),
    trigger: text("trigger", { enum: ["schedule", "manual", "retry"] }).notNull(),
    attempt: integer("attempt").notNull().default(1),
    nextAttemptAt: timestamp("next_attempt_at", { withTimezone: true }),
    startedAt: timestamp("started_at", { withTimezone: true }),
    endedAt: timestamp("ended_at", { withTimezone: true }),
    endedReason: text("ended_reason"),
    durationSeconds: integer("duration_seconds"),
    transcript: text("transcript"),
    transcriptExpiresAt: timestamp("transcript_expires_at", { withTimezone: true }),
    extractedPlan: jsonb("extracted_plan"),
    importResult: jsonb("import_result").$type<CallImportResult>(),
    summary: text("summary"),
    costCents: integer("cost_cents"),
    processingAttempts: integer("processing_attempts").notNull().default(0),
    /** Set while a worker is extracting/applying this call, so two workers never apply it twice. */
    processingLeaseUntil: timestamp("processing_lease_until", { withTimezone: true }),
    processedAt: timestamp("processed_at", { withTimezone: true }),
    error: text("error"),
    ...timestamps,
  },
  (table) => [
    index("calls_user_created_idx").on(table.userId, table.createdAt),
    index("calls_status_idx").on(table.status),
  ],
);

export type User = typeof user.$inferSelect;
export type Week = typeof weeks.$inferSelect;
export type Task = typeof tasks.$inferSelect;
export type PlanningSchedule = typeof planningSchedules.$inferSelect;
export type Call = typeof calls.$inferSelect;
